  ]$j$::jsonb,
  $j$[
    {"question": "Avant de réserver, un client voudrait votre numéro de téléphone. Vous…", "options": ["l'écrivez en lettres dans votre proposition", "l'invitez à réserver sur la plateforme", "lui donnez votre adresse e-mail à la place"]},
    {"question": "Une offre claire indique…", "options": ["le type de séance, la durée, le lieu et le prix", "seulement un prix « à discuter »", "un texte général sur votre passion du sport"]},
    {"question": "La veille d'une séance, vous avez un empêchement. Vous…", "options": ["ne venez pas, le client comprendra", "envoyez un ami vous remplacer sans prévenir", "prévenez le client au plus tôt et proposez un autre créneau"]},
    {"question": "Un client laisse un avis négatif. Vous…", "options": ["le prenez personnellement et laissez tomber ce client", "restez calme et retenez ce qui peut être amélioré", "demandez à des amis de publier des avis positifs"]},
    {"question": "Une séance organisée en dehors de MAWHIBA est…", "options": ["couverte par l'assurance Star comme les autres", "couverte seulement si le client paie en espèces", "non couverte : seules les séances réservées et payées sur la plateforme sont assurées"]}
  ]$j$::jsonb,
  '{1,0,2,1,2}'::int[],
  4
)
on conflict (slug) do update set
  title = excluded.title,
  description = excluded.description,
  lessons = excluded.lessons,
  quiz = excluded.quiz,
  answer_key = excluded.answer_key,
  pass_score = excluded.pass_score;

-- migration: 20261008000001_events.sql
-- Monthly community event: admins publish it, clients and coaches register for free (capacity-limited).
-- `registered` is a counter kept by the RPCs under a row lock, so public pages show spots left
-- without exposing who registered.

create table public.events (
  id uuid primary key default gen_random_uuid(),
  title text not null check (char_length(title) between 3 and 120),
  description text not null default '' check (char_length(description) <= 2000),
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  location text not null check (char_length(location) between 2 and 200),
  capacity int not null check (capacity between 1 and 10000),
  registered int not null default 0 check (registered between 0 and capacity),
  created_at timestamptz not null default now(),
  check (ends_at > starts_at)
);
create index events_starts_idx on public.events (starts_at);

create table public.event_registrations (
  event_id uuid not null references public.events (id) on delete cascade,
  user_id uuid not null references public.profiles (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (event_id, user_id)
);

alter table public.events enable row level security;
alter table public.event_registrations enable row level security;
revoke all on public.events, public.event_registrations from anon, authenticated;

grant select on public.events to anon, authenticated;
create policy events_select on public.events for select using (true);

grant select on public.event_registrations to authenticated;
create policy event_registrations_select on public.event_registrations for select
  using (user_id = auth.uid() or public.is_admin());

create function public.register_event(event_id uuid) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := public.assert_role(array['client', 'coach']::user_role[]);
  v_e events;
begin
  select * into v_e from events e where e.id = register_event.event_id for update;
  if not found then raise exception 'NOT_FOUND'; end if;
  if v_e.starts_at <= now() then raise exception 'EVENT_PAST'; end if;
  if exists (select 1 from event_registrations r where r.event_id = v_e.id and r.user_id = v_uid) then return; end if;
  if v_e.registered >= v_e.capacity then raise exception 'EVENT_FULL'; end if;
  insert into event_registrations (event_id, user_id) values (v_e.id, v_uid);
  update events set registered = registered + 1 where id = v_e.id;
end $$;

create function public.unregister_event(event_id uuid) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := public.assert_role(array['client', 'coach']::user_role[]);
  v_e events;
begin
  select * into v_e from events e where e.id = unregister_event.event_id for update;
  if not found then raise exception 'NOT_FOUND'; end if;
  if v_e.starts_at <= now() then raise exception 'EVENT_PAST'; end if;
  delete from event_registrations r where r.event_id = v_e.id and r.user_id = v_uid;
  if found then update events set registered = registered - 1 where id = v_e.id; end if;
end $$;

create function public.admin_create_event(
  title text, description text, starts_at timestamptz, ends_at timestamptz, location text, capacity int
) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_id uuid;
begin
  perform public.assert_role(array['admin']::user_role[]);
  if admin_create_event.starts_at <= now() then raise exception 'EVENT_PAST'; end if;
  insert into events (title, description, starts_at, ends_at, location, capacity)
  values (trim(admin_create_event.title), trim(coalesce(admin_create_event.description, '')), admin_create_event.starts_at,
          admin_create_event.ends_at, trim(admin_create_event.location), admin_create_event.capacity)
  returning id into v_id;
  return v_id;
end $$;

revoke execute on function
  public.register_event(uuid), public.unregister_event(uuid),
  public.admin_create_event(text, text, timestamptz, timestamptz, text, int)
  from public, anon, authenticated;
grant execute on function
  public.register_event(uuid), public.unregister_event(uuid),
  public.admin_create_event(text, text, timestamptz, timestamptz, text, int)
  to authenticated;

-- migration: 20261009000001_locations.sql
-- Coach training location. The exact pin is private (owner + admin) in `coach_locations`;
-- the public only sees `coach_profiles.map_lat/map_lng`, rounded to 2 decimals (~1 km) by trigger.
-- Editing the location is not a verified claim: it never resets `verified`.

alter table public.coach_profiles
  add column base_label text check (char_length(base_label) <= 80),
  add column service_radius_km int not null default 10 check (service_radius_km between 1 and 100),
  add column map_lat double precision,
  add column map_lng double precision;

create table public.coach_locations (
  coach_id uuid primary key references public.coach_profiles (user_id) on delete cascade,
  lat double precision not null check (lat between 30 and 38), -- Tunisia bounding box
  lng double precision not null check (lng between 7 and 12)
);

create function public.sync_coach_map_point() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'DELETE' then
    update coach_profiles set map_lat = null, map_lng = null where user_id = old.coach_id;
  else
    update coach_profiles set map_lat = round(new.lat::numeric, 2)::float8, map_lng = round(new.lng::numeric, 2)::float8
     where user_id = new.coach_id;
  end if;
  return null;
end $$;

create trigger coach_locations_sync after insert or update or delete on public.coach_locations
  for each row execute function public.sync_coach_map_point();

-- Great-circle distance (haversine, R = 6371 km). Mirror of src/lib/geo.ts `distanceKm`.
create function public.distance_km(lat1 float8, lng1 float8, lat2 float8, lng2 float8) returns float8
language sql immutable as $$
  select 2 * 6371 * asin(sqrt(
    power(sin(radians(lat2 - lat1) / 2), 2)
    + cos(radians(lat1)) * cos(radians(lat2)) * power(sin(radians(lng2 - lng1) / 2), 2)
  ))
$$;

-- ---------- RLS & privileges ----------
alter table public.coach_locations enable row level security;
revoke all on public.coach_locations from anon, authenticated;
grant select, insert (coach_id, lat, lng), update (lat, lng), delete on public.coach_locations to authenticated;

create policy coach_locations_select on public.coach_locations for select
  using (coach_id = auth.uid() or public.is_admin());
create policy coach_locations_write on public.coach_locations for all
  using (coach_id = auth.uid()) with check (coach_id = auth.uid() and public.auth_role() = 'coach');

-- map_lat/map_lng are written by the trigger only.
grant update (base_label, service_radius_km) on public.coach_profiles to authenticated;

revoke execute on function public.sync_coach_map_point(), public.distance_km(float8, float8, float8, float8)
  from public, anon, authenticated;
grant execute on function public.distance_km(float8, float8, float8, float8) to anon, authenticated;
